/**
 * Incremental change to the chat list, mirroring eyeball-im `VectorDiff`.
 * Apply the diffs of one `on_update` call in order.
 */

public enum ChatListDiff: Equatable, Hashable {
    
    case append(values: [ChatSummary]
    )
    case clear
    case pushFront(value: ChatSummary
    )
    case pushBack(value: ChatSummary
    )
    case popFront
    case popBack
    case insert(index: UInt32, value: ChatSummary
    )
    case set(index: UInt32, value: ChatSummary
    )
    case remove(index: UInt32
    )
    case truncate(length: UInt32
    )
    case reset(values: [ChatSummary]
    )





}

#if compiler(>=6)
extension ChatListDiff: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeChatListDiff: FfiConverterRustBuffer {
    typealias SwiftType = ChatListDiff

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ChatListDiff {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .append(values: try FfiConverterSequenceTypeChatSummary.read(from: &buf)
        )
        
        case 2: return .clear
        
        case 3: return .pushFront(value: try FfiConverterTypeChatSummary.read(from: &buf)
        )
        
        case 4: return .pushBack(value: try FfiConverterTypeChatSummary.read(from: &buf)
        )
        
        case 5: return .popFront
        
        case 6: return .popBack
        
        case 7: return .insert(index: try FfiConverterUInt32.read(from: &buf), value: try FfiConverterTypeChatSummary.read(from: &buf)
        )
        
        case 8: return .set(index: try FfiConverterUInt32.read(from: &buf), value: try FfiConverterTypeChatSummary.read(from: &buf)
        )
        
        case 9: return .remove(index: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 10: return .truncate(length: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 11: return .reset(values: try FfiConverterSequenceTypeChatSummary.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ChatListDiff, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .append(values):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeChatSummary.write(values, into: &buf)
            
        
        case .clear:
            writeInt(&buf, Int32(2))
        
        
        case let .pushFront(value):
            writeInt(&buf, Int32(3))
            FfiConverterTypeChatSummary.write(value, into: &buf)
            
        
        case let .pushBack(value):
            writeInt(&buf, Int32(4))
            FfiConverterTypeChatSummary.write(value, into: &buf)
            
        
        case .popFront:
            writeInt(&buf, Int32(5))
        
        
        case .popBack:
            writeInt(&buf, Int32(6))
        
        
        case let .insert(index,value):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterTypeChatSummary.write(value, into: &buf)
            
        
        case let .set(index,value):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterTypeChatSummary.write(value, into: &buf)
            
        
        case let .remove(index):
            writeInt(&buf, Int32(9))
            FfiConverterUInt32.write(index, into: &buf)
            
        
        case let .truncate(length):
            writeInt(&buf, Int32(10))
            FfiConverterUInt32.write(length, into: &buf)
            
        
        case let .reset(values):
            writeInt(&buf, Int32(11))
            FfiConverterSequenceTypeChatSummary.write(values, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeChatListDiff_lift(_ buf: RustBuffer) throws -> ChatListDiff {
    return try FfiConverterTypeChatListDiff.lift(buf)
}

