/**
 * Error returned by every fallible gim-core call.
 *
 * Kotlin: `GimException.<Variant>`; Swift: `GimError.<Variant>`.
 */
public 
enum GimError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The server could not be reached or the connection broke.
     */
    case Network(reason: String
    )
    /**
     * The call needs a session: create an identity, restore one from its
     * recovery code or link this device first. Also returned after
     * `sign_out` and once the hub reports this device as revoked.
     */
    case NotRegistered
    /**
     * An argument was rejected before anything was sent.
     */
    case InvalidInput(reason: String
    )
    /**
     * The chat, message, user or media does not exist locally or on the server.
     */
    case NotFound(reason: String
    )
    /**
     * MLS or media encryption/decryption failed.
     */
    case Crypto(reason: String
    )
    /**
     * The local database or file system failed.
     */
    case Storage(reason: String
    )
    /**
     * The hub answered with a non-success HTTP status.
     */
    case Server(status: UInt16, reason: String
    )
    /**
     * The hub is throttling the call (HTTP 429 `rate_limited`) or a remote
     * hub is unavailable (HTTP 503 `peer_unavailable`), and gim-core's
     * bounded retries are used up; try again after `retry_after_secs`.
     */
    case RetryLater(status: UInt16, retryAfterSecs: UInt64, reason: String
    )
    /**
     * The operation was cancelled (sign-out, `stop_sync`, `cancel_send`).
     */
    case Cancelled
    /**
     * The call is part of the API contract but not implemented yet.
     */
    case NotImplemented
    /**
     * A bug or an unexpected failure inside gim-core or a platform callback.
     */
    case Internal(reason: String
    )
    /**
     * The call sends to (or changes) a chat this device is leaving or has
     * left. `state` is `Leaving` or `Left`; see `ChatState`.
     */
    case ChatNotActive(chatId: String, state: ChatState
    )
    /**
     * The server at the configured URL did not prove that it is the
     * expected hub at that URL (a wrong URL, or a relay in between); the
     * device did not sign in there. Check the hub URL.
     */
    case HubNotVerified(reason: String
    )
    /**
     * `remove_hub` without `confirm_owned_groups`: the hub owns
     * `group_count` chats of this user. They are not moved; after the
     * removal they stay reachable through the other members' hubs. Ask
     * the user, then call `remove_hub` again with `confirm_owned_groups`.
     */
    case HubOwnsGroups(hubId: String, groupCount: UInt32
    )
    /**
     * The hub is the only listed hub and cannot be removed.
     */
    case LastHub(hubId: String
    )
    /**
     * The hub is the one this client was created for (`HubInfo.is_home`)
     * and cannot be removed.
     */
    case HomeHub(hubId: String
    )
    /**
     * Messages or membership changes sent through the hub are not settled
     * yet, so it cannot be removed now; try again later.
     */
    case HubNotDrained(hubId: String, reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension GimError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGimError: FfiConverterRustBuffer {
    typealias SwiftType = GimError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GimError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotRegistered
        case 3: return .InvalidInput(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .NotFound(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Crypto(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Server(
            status: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .RetryLater(
            status: try FfiConverterUInt16.read(from: &buf), 
            retryAfterSecs: try FfiConverterUInt64.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Cancelled
        case 10: return .NotImplemented
        case 11: return .Internal(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 12: return .ChatNotActive(
            chatId: try FfiConverterString.read(from: &buf), 
            state: try FfiConverterTypeChatState.read(from: &buf)
            )
        case 13: return .HubNotVerified(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 14: return .HubOwnsGroups(
            hubId: try FfiConverterString.read(from: &buf), 
            groupCount: try FfiConverterUInt32.read(from: &buf)
            )
        case 15: return .LastHub(
            hubId: try FfiConverterString.read(from: &buf)
            )
        case 16: return .HomeHub(
            hubId: try FfiConverterString.read(from: &buf)
            )
        case 17: return .HubNotDrained(
            hubId: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GimError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Network(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotRegistered:
            writeInt(&buf, Int32(2))
        
        
        case let .InvalidInput(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Crypto(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Server(status,reason):
            writeInt(&buf, Int32(7))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .RetryLater(status,retryAfterSecs,reason):
            writeInt(&buf, Int32(8))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterUInt64.write(retryAfterSecs, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(9))
        
        
        case .NotImplemented:
            writeInt(&buf, Int32(10))
        
        
        case let .Internal(reason):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ChatNotActive(chatId,state):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterTypeChatState.write(state, into: &buf)
            
        
        case let .HubNotVerified(reason):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .HubOwnsGroups(hubId,groupCount):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(hubId, into: &buf)
            FfiConverterUInt32.write(groupCount, into: &buf)
            
        
        case let .LastHub(hubId):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(hubId, into: &buf)
            
        
        case let .HomeHub(hubId):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(hubId, into: &buf)
            
        
        case let .HubNotDrained(hubId,reason):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(hubId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


