    )
    case pushBack(value: TimelineItem
    )
    case popFront
    case popBack
    case insert(index: UInt32, value: TimelineItem
    )
    case set(index: UInt32, value: TimelineItem
    )
    case remove(index: UInt32
    )
    case truncate(length: UInt32
    )
    case reset(values: [TimelineItem]
    )





}

